  ('6mm ID Linear Ball Bearing (12mm OD, 35mm Length) - 2 Pack', '1612-0612-0035', null, 'goBILDA', null, true, 'https://www.gobilda.com/6mm-id-linear-ball-bearing-12mm-od-35mm-length-2-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/852/images/4671/1612-0612-0035__18531__19993.1701992265.386.513.jpg?c=1', 'MOTION / Bearings / Linear Ball Bearings', 'gobilda'),
  ('8mm ID Linear Ball Bearing (15mm OD, 24mm Length) - 2 Pack', '1612-0815-0024', null, 'goBILDA', null, true, 'https://www.gobilda.com/8mm-id-linear-ball-bearing-15mm-od-24mm-length-2-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/356/images/2632/1612-0815-0024__61769__32486.1701991650.386.513.jpg?c=1', 'MOTION / Bearings / Linear Ball Bearings', 'gobilda'),
  ('8mm ID Linear Ball Bearing (15mm OD, 45mm Length) - 2 Pack', '1612-0815-0045', null, 'goBILDA', null, true, 'https://www.gobilda.com/8mm-id-linear-ball-bearing-15mm-od-45mm-length-2-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/358/images/2638/1612-0815-0045__07073__20285.1701991652.386.513.jpg?c=1', 'MOTION / Bearings / Linear Ball Bearings', 'gobilda'),
  ('12mm ID Linear Ball Bearing (21mm OD, 30mm Length) - 2 Pack', '1612-1221-0030', null, 'goBILDA', null, true, 'https://www.gobilda.com/12mm-id-linear-ball-bearing-21mm-od-30mm-length-2-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/360/images/2645/1612-1221-0030__61271__68405.1701991654.386.513.jpg?c=1', 'MOTION / Bearings / Linear Ball Bearings', 'gobilda'),
  ('12mm ID Linear Ball Bearing (21mm OD, 57mm Length) - 2 Pack', '1612-1221-0057', null, 'goBILDA', null, true, 'https://www.gobilda.com/12mm-id-linear-ball-bearing-21mm-od-57mm-length-2-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/363/images/2651/1612-1221-0057__84150__48494.1701991656.386.513.jpg?c=1', 'MOTION / Bearings / Linear Ball Bearings', 'gobilda'),
  ('1613 Series Thrust Ball Bearing (6mm ID x 14mm OD, 5mm Thickness)', '1613-0514-0006', 'Our 6mm thrust bearings are able to slide over 6mm round shafting and 6mm D-shafting to isolate potential axial loads from other areas of your assembly.', 'goBILDA', null, true, 'https://www.gobilda.com/1613-series-thrust-ball-bearing-6mm-id-x-14mm-od-5mm-thickness/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/854/images/4677/1613-0514-0006__00217__12971.1701992267.386.513.jpg?c=1', 'MOTION / Bearings / Thrust Ball Bearings', 'gobilda'),
  ('8mm ID Thrust Ball Bearing (15.5mm OD, 5mm Thickness)', '1613-0516-0008', 'Our 8mm thrust bearings can be used with 8mm diameter shafting and 8mm lead screws in order to isolate an axial load from other areas of your assembly.', 'goBILDA', null, true, 'https://www.gobilda.com/8mm-id-thrust-ball-bearing-15-5mm-od-5mm-thickness/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/856/images/4683/1613-0516-0008__36332__25769.1701992269.386.513.jpg?c=1', 'MOTION / Bearings / Thrust Ball Bearings', 'gobilda'),
  ('12mm ID Thrust Ball Bearing (12mm ID x 21mm OD, 5mm Thickness)', '1613-0521-0012', 'Our 12mm thrust bearings are compatible with 12mm round shafting as well as 12mm REX shafting. Do your assembly a favor by isolating the axial load using these thrust bearings.', 'goBILDA', null, true, 'https://www.gobilda.com/12mm-id-thrust-ball-bearing-12mm-id-x-21mm-od-5mm-thickness/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1130/images/5653/1613-0521-0012__82791__00832.1701992601.386.513.jpg?c=1', 'MOTION / Bearings / Thrust Ball Bearings', 'gobilda'),
  ('Dual-Bearing Pillow Block (4mm Bore)', '1614-0016-0004', 'This pillow block is an all-in-one(2) solution to provide support to a 4mm diameter shaft. Two bearings, as found in this Dual-Bearing Pillow Block, are critical in providing shaft support when dealing with a cantilevered load on an otherwise unsupported shaft. That''s why this pillow block shines when there''s only one(3) surface available to mount a bearing. Simply fasten it on the goBILDA® 16mm pattern using its threaded or thru-holes, and put your project in motion!', 'goBILDA', null, true, 'https://www.gobilda.com/dual-bearing-pillow-block-4mm-bore/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1949/images/10540/1614-0016-0004-Ang1__85228__34074.1701994138.386.513.jpg?c=1', 'MOTION / Bearings / Dual-Bearing Pillow Blocks', 'gobilda'),
  ('Dual-Bearing Pillow Block (6mm Bore)', '1614-0016-0006', 'This pillow block is an all-in-one(4) solution to provide support to a 6mm diameter round shaft or 6mm diameter D-shaft. Two bearings, as found in this Dual Bearing Pillow Block, are critical in providing shaft support when dealing with a cantilevered load on an otherwise unsupported shaft. That''s why this pillow block shines when there''s only one(5) surface available to mount a bearing. Simply fasten it on the goBILDA® 16mm pattern using its threaded or thru-holes, and put your project in motion!', 'goBILDA', null, true, 'https://www.gobilda.com/dual-bearing-pillow-block-6mm-bore/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1830/images/9863/1614-0016-0006_Ang1__05243__77238.1701993924.386.513.jpg?c=1', 'MOTION / Bearings / Dual-Bearing Pillow Blocks', 'gobilda'),
  ('Dual-Bearing Pillow Block (8mm Bore)', '1614-0016-0008', 'This pillow block is an all-in-one(6) solution to provide support to an 8mm diameter shaft. Two bearings, as found in this Dual-Bearing Pillow Block, are critical in providing shaft support when dealing with a cantilevered load on an otherwise unsupported shaft. That''s why this pillow block shines when there''s only one(7) surface available to mount a bearing. Simply fasten it on the goBILDA® 16mm pattern using its threaded or thru-holes, and put your project in motion!', 'goBILDA', null, true, 'https://www.gobilda.com/dual-bearing-pillow-block-8mm-bore/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1832/images/9871/1614-0016-0008_Ang1__79641__42723.1701993927.386.513.jpg?c=1', 'MOTION / Bearings / Dual-Bearing Pillow Blocks', 'gobilda'),
  ('Dual-Bearing Pillow Block (8mm REX® Bore)', '1614-0016-4008', 'This pillow block is an all-in-one(8) solution to provide support to an 8mm REX® shaft. Two bearings, as found in this Dual-Bearing Pillow Block, are critical in providing shaft support when dealing with a cantilevered load on an otherwise unsupported shaft. That''s why this pillow block shines when there''s only one(9) surface available to mount a bearing. Simply fasten it on the goBILDA® 16mm pattern using its threaded or thru-holes, and put your project in motion!', 'goBILDA', null, true, 'https://www.gobilda.com/dual-bearing-pillow-block-8mm-rex-bore/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1834/images/9896/1614-0016-4008_Ang1__39929__08072.1701993934.386.513.jpg?c=1', 'MOTION / Bearings / Dual-Bearing Pillow Blocks', 'gobilda'),
  ('1614 Series Dual Pillow Block (16mm Length, 6mm Bore)', '1614-1616-0006', 'Having two bearings mounted in one(10) pillow block provides radial support to a shaft that passes through. The counterbored holes on the outsides allow the screw heads to rest well below the surface so they don''t interfere with rotating parts (hubs, collars, couplers, etc.). Threaded holes are also available so you can fasten the Dual Pillow Block to a part that has thru-holes on the 16mm pattern.', 'goBILDA', null, true, 'https://www.gobilda.com/1614-series-dual-pillow-block-16mm-length-6mm-bore/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1098/images/5471/1614-01616-0006__74075__19846.1701992541.386.513.jpg?c=1', null, 'gobilda'),
  ('1616 Series Drop-Center Bearing Plate (2mm Drop) - 4 Pack', '1616-0016-0002', 'This drop-center plate is designed to give you a way to mount your bearing 2mm offset from its normal position. A common use would be on a 6-wheel chassis. They would allow you to "drop" the center wheels or raise the outer wheels in order to focus the load on the center wheels of the chassis. This effectively shortens the wheelbase resulting in a chassis that will turn quicker and easier.', 'goBILDA', null, true, 'https://www.gobilda.com/1616-series-drop-center-bearing-plate-2mm-drop-4-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1723/images/9005/1616-0016-0002_Ang7__08239__79390.1701993652.386.513.jpg?c=1', 'MOTION / Bearings / Drop-Center Bearing Plates', 'gobilda'),
  ('1616 Series Drop-Center Bearing Plate (32mm Pattern, 2mm Drop) - 4 Pack', '1616-0032-0002', 'Drop-center bearing plates fasten to your chassis, on the 32mm pattern, providing a 2mm offset of the 14mm hole. These plates are extremely handy for 6 wheel chassis builds where you want the center wheels to have more of the overall load than the front and/or back. Unloading wheels located on the corners of your skid-steer chassis will provide much quicker turning and drive like a chassis with a much shorter wheelbase. Given the 4mm plate thickness, the 1611 Series Bearings that have a 14mm…', 'goBILDA', null, true, 'https://www.gobilda.com/1616-series-drop-center-bearing-plate-32mm-pattern-2mm-drop-4-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1355/images/6631/1616-0032-0002__26526__67983.1701992912.386.513.jpg?c=1', null, 'gobilda'),
  ('4mm Bore Flat Pillow Block (16mm x 32mm Mounting Pattern) - 2 Pack', '1621-1632-0004', 'This 4mm Bore Flat Pillow Block consists of a bearing and the flat plastic casing it press-fits into. The flange of the bearing is flush with the back of the casing so that when the pillow block is bolted to a flat surface, the bearing is fully constrained. This pillow block''s compact dimensions and goBILDA® 16mm pattern holes (with two additional 8mm pattern center holes) allow for unique use-cases. You can fit it side-by-side with other Flat Pillow Blocks so that their shafts are held 24mm…', 'goBILDA', null, true, 'https://www.gobilda.com/4mm-bore-flat-pillow-block-16mm-x-32mm-mounting-pattern-2-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1943/images/10493/1621-1632-0004_Ang1__77594__13698.1701994125.386.513.jpg?c=1', 'MOTION / Bearings / Face Thru-Hole Pillow Blocks', 'gobilda'),
  ('6mm Bore Flat Pillow Block (16mm x 32mm Mounting Pattern) - 2 Pack', '1621-1632-0006', 'This 6mm Bore Flat Pillow Block consists of a bearing and the flat plastic casing it press-fits into. The flange of the bearing is flush with the back of the casing so that when the pillow block is bolted to a flat surface, the bearing is fully constrained. This pillow block''s compact dimensions and goBILDA® 16mm pattern holes (with two additional 8mm pattern center holes) allow for unique use-cases. You can fit it side-by-side with other Flat Pillow Blocks so that their shafts are held 24mm…', 'goBILDA', null, true, 'https://www.gobilda.com/6mm-bore-flat-pillow-block-16mm-x-32mm-mounting-pattern-2-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1951/images/10547/1621-1632-0006_Ang1__58653__99332.1701994140.386.513.jpg?c=1', 'MOTION / Bearings / Face Thru-Hole Pillow Blocks', 'gobilda'),
  ('8mm Bore Flat Pillow Block (16mm x 32mm Mounting Pattern) - 2 Pack', '1621-1632-0008', 'This 8mm Bore Flat Pillow Block consists of a bearing and the flat plastic casing it press-fits into. The flange of the bearing is flush with the back of the casing so that when the pillow block is bolted to a flat surface, the bearing is fully constrained. This pillow block''s compact dimensions and goBILDA® 16mm pattern holes (with two additional 8mm pattern center holes) allow for unique use-cases. You can fit it side-by-side with other Flat Pillow Blocks so that their shafts are held 24mm…', 'goBILDA', null, true, 'https://www.gobilda.com/8mm-bore-flat-pillow-block-16mm-x-32mm-mounting-pattern-2-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1946/images/10520/1621-1632-0008_Ang1__37788__09452.1701994132.386.513.jpg?c=1', 'MOTION / Bearings / Face Thru-Hole Pillow Blocks', 'gobilda'),
  ('8mm REX® Bore Flat Pillow Block (16mm x 32mm Mounting Pattern) - 2 Pack', '1621-1632-4008', 'This 8mm REX® Bore Flat Pillow Block consists of a bearing and the flat plastic casing it press-fits into. The flange of the bearing is flush with the back of the casing so that when the pillow block is bolted to a flat surface, the bearing is fully constrained. This pillow block''s compact dimensions and goBILDA® 16mm pattern holes (with two additional 8mm pattern center holes) allow for unique use-cases. You can fit it side-by-side with other Flat Pillow Blocks so that their shafts are held…', 'goBILDA', null, true, 'https://www.gobilda.com/8mm-rex-bore-flat-pillow-block-16mm-x-32mm-mounting-pattern-2-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1948/images/10535/1621-1632-4008_Ang1__83555__53191.1701994136.386.513.jpg?c=1', 'MOTION / Bearings / Face Thru-Hole Pillow Blocks', 'gobilda'),
  ('12mm Bore, Heavy-Duty Flange-Mount Bearing Pillow Block', '1622-0032-0012', 'Need a big bearing for a big job? This hefty pillow block offers extreme support to 12mm diameter shafting with its massive 12mm bearing! The bearing''s seals keep out moisture and debris even when your project is getting hands-on with terrain. This pillow block has thru-holes, spaced 32mm apart, that are highly compatible across the goBILDA® ecosystem, and the hex counterbores enable one(11)-tool installation when using M4 hex nuts.', 'goBILDA', null, true, 'https://www.gobilda.com/12mm-bore-heavy-duty-flange-mount-bearing-pillow-block/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1939/images/10484/1622-0032-0012__35867__17421.1701994120.386.513.jpg?c=1', 'MOTION / Bearings / Face Thru-Hole Pillow Blocks', 'gobilda'),
  ('12mm ID Non-Flanged Ball Bearing (Sealed, 32mm OD, 10mm Thickness) - 2 Pack', '1626-1032-0012', 'This 12mm Bore Non-Flanged Ball Bearing provides rotation support to 12mm diameter shafting, including 12mm REX™ shafting. The rubber seals help to ward off moisture and contaminants from interfering with the bearing''s rotation—a fantastic feature for applications that engage with the terrain! While this bearing is a perfect fit with any of our 32mm bore clamping mounts for the creation of a 12mm Bore Pillow Block you can mount to your liking, it''s also available pre-installed in the 12mm Bore…', 'goBILDA', null, true, 'https://www.gobilda.com/12mm-id-non-flanged-ball-bearing-sealed-32mm-od-10mm-thickness-2-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/2404/images/15058/Ang1_2__17025__75564.1752165957.386.513.jpg?c=1', 'MOTION / Bearings / Non-Flanged Ball Bearings', 'gobilda'),
  ('1700 Series Face Tapped Stepper Motor Mount (NEMA 8)', '1700-0016-0008', 'This mount will fasten to the face of a NEMA 8 stepper motor using the supplied pan head screws. The threaded holes are on the 16mm pattern so that you can fasten the mount to any pattern plate or channel using M4 screws.', 'goBILDA', null, true, 'https://www.gobilda.com/1700-series-face-tapped-stepper-motor-mount-nema-8/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/364/images/2656/1700-0016-0008__12364__49487.1701991657.386.513.jpg?c=1', 'MOTION / Motors / Motor Mounts', 'gobilda'),
  ('1700 Series Face Tapped Stepper Motor Mount (NEMA 11)', '1700-0016-0011', 'The NEMA 11 stepper motor mount is able to fasten to the face of a NEMA 11 motor using the supplied pan head screws. The screws are recessed into the counterbored holes in order to leave a smooth mounting surface. There are two thru-holes and two threaded holes on the 16mm pattern so that you have options for the best way to attach the mount to your structure.', 'goBILDA', null, true, 'https://www.gobilda.com/1700-series-face-tapped-stepper-motor-mount-nema-11/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/366/images/2672/1700-0016-0011__24506__80519.1701991662.386.513.jpg?c=1', 'MOTION / Motors / Motor Mounts', 'gobilda'),
  ('1700 Series Face Tapped Stepper Motor Mount (NEMA 14)', '1700-0016-0014', 'This mount allows you to fasten a NEMA 14 motor to any goBILDA component that contains the 16mm pattern. The included M3 socket head screws hold the motor to the mount and the heads will remain below the mounting surface.', 'goBILDA', null, true, 'https://www.gobilda.com/1700-series-face-tapped-stepper-motor-mount-nema-14/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/368/images/2680/1700-0016-0014__80415__75012.1701991664.386.513.jpg?c=1', 'MOTION / Motors / Motor Mounts', 'gobilda'),
  ('1700 Series Face Tapped Stepper Motor Mount (NEMA 17)', '1700-0016-0017', 'This mount allows you to fasten a NEMA 17 motor to any goBILDA component that contains the 16mm pattern. The included M3 socket head screws hold the motor to the mount and the heads will remain below the mounting surface.', 'goBILDA', null, true, 'https://www.gobilda.com/1700-series-face-tapped-stepper-motor-mount-nema-17/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/370/images/2687/1700-0016-0017__40120__74506.1701991666.386.513.jpg?c=1', 'MOTION / Motors / Motor Mounts', 'gobilda'),
  ('1700 Series Face Tapped Stepper Motor Mount (NEMA 23)', '1700-0016-0023', 'The NEMA 23 motor mount provides a clean and simple way to fasten a NEMA 23 stepper motor to your project. The mount has both threaded and thru-holes on the 16mm and 32mm patterns. The included M5 screws will pass through the tabs of the motor mount and thread into the motor mount for a solid and reliable connection.', 'goBILDA', null, true, 'https://www.gobilda.com/1700-series-face-tapped-stepper-motor-mount-nema-23/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/362/images/2655/1700-0016-0023__69236__77245.1701991657.386.513.jpg?c=1', 'MOTION / Motors / Motor Mounts', 'gobilda'),
  ('1701 Series Face Tapped Motor Mount (16-3)', '1701-0016-0003', 'This motor mount is able to fasten to the face of a 5201 Series Gear Motor (as well as other spur motors that contain a 31mm bolt-circle) while centering the output shaft with the goBILDA pattern. We''ve included (6) M3 x 6mm screws to hold the motor mount to the face of the gearbox. There are threaded holes on both the 16mm pattern as well as the 32mm so that you have options where and how it fastens to your chassis. The 7mm overall width sets the motor back so that the motor shaft bushing…', 'goBILDA', null, true, 'https://www.gobilda.com/1701-series-face-tapped-motor-mount-16-3/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/365/images/2670/1701-0016-0003-Beauty-1__59469__90451.1701991661.386.513.jpg?c=1', 'MOTION / Motors / Motor Mounts / Motor Mounts for REV Robotics Motors', 'gobilda'),
  ('1701 Series Face Tapped Motor Mount (32-1)', '1701-0032-0001', 'This motor mount is designed to be used with the REV Robotics Core Hex Motor. Given this motor is used in FIRST Tech Challenge, we want to provide teams the opportunity to easily integrate the motor into their goBILDA framework. When you use two mounts (one(12) on each side), the side-to-side measurement will be exactly 43mm so the assembly will slide down inside 1120 Series U-Channel perfectly and fasten using M4 x 6mm length screws.', 'goBILDA', null, true, 'https://www.gobilda.com/1701-series-face-tapped-motor-mount-32-1/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1073/images/5276/1701-0032-0001__90590__57933.1701992484.386.513.jpg?c=1', 'MOTION / Motors / Motor Mounts / Motor Mounts for REV Robotics Motors', 'gobilda'),
  ('1702 Series Quad Block Motor Mount (32-1)', '1702-0032-0001', 'Get compatibility and versatility all in one(13) motor mount! The Quad Block Motor Mount contains many different hole patterns in order to work with many common motors found on the market. The mount is then able to fasten to your project via the threaded holes in the sides, or with the threaded holes in the face of the mount. This mount comes with four 6mm length M3 screws (SKU: 2800-0003-0006).', 'goBILDA', null, true, 'https://www.gobilda.com/1702-series-quad-block-motor-mount-32-1/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/367/images/2678/1702-0032-0001__10754__93160.1701991663.386.513.jpg?c=1', 'MOTION / Motors / Motor Mounts / Motor Mounts for REV Robotics Motors', 'gobilda'),
  ('1702 Series Quad Block Motor Mount (32-2)', '1702-0032-0002', 'This motor mount is a solid way to fasten a Neverest Orbital 20 or a REV HD Hex Planetary Gear Motor to goBILDA. The included M3 x 10mm length screws maximize the thread depth found on either motor so that you don''t have to worry about your motors coming loose during the heat of competition. The ''Quad Block'' style mount provides threaded holes from the sides, commonly used when mounting inside of 1120 Series U-Channel, as well as threaded holes on the face. The threaded posts of this mount…', 'goBILDA', null, true, 'https://www.gobilda.com/1702-series-quad-block-motor-mount-32-2/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1123/images/5607/1702-0032-0002__77779__83053.1701992587.386.513.jpg?c=1', 'MOTION / Motors / Motor Mounts / Motor Mounts for REV Robotics Motors / Motor Mounts for REV HD Hex Planetary Gear Motor', 'gobilda'),
  ('1702 Series Quad Block Motor Mount (43-1)', '1702-0043-0001', 'This Quad Block Motor Mount is an adaptor with a vast range of compatibility. Featuring a variety of different hole patterns in its face, it provides for the attachment of many motors (such as Neverest Orbital and REV motors) to structure components within the goBILDA® build system. Threaded holes in the face and sides of the mount allow for versatile installations, especially within 1120 Series U-Channel. The "posts" provide clearance and adjustability—in the majority of use-cases where your…', 'goBILDA', null, true, 'https://www.gobilda.com/1702-series-quad-block-motor-mount-43-1/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/2465/images/15623/Ang1__02790__99318.1764191629.386.513.jpg?c=1', 'MOTION / Motors / Motor Mounts / Motor Mounts for REV Robotics Motors', 'gobilda'),
  ('1702 Series Quad Block Motor Mount (43-3)', '1702-0043-0003', 'This motor mount aligns with the REV UltraPlanetary Gearbox and provides a plethora of mounting options with your goBILDA chassis. The C-shaped design provides a thru-way to access the set-screw on the UltraPlanetary''s output hub. If 5mm hex isn''t your thing, beef up the output with our 8mm REX shaft which is able to bolt directly onto the UltraPlanetary using the REV orbital pattern found on the face of their output hub.', 'goBILDA', null, true, 'https://www.gobilda.com/1702-series-quad-block-motor-mount-43-3/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1359/images/6647/1702-0043-0003__59689__91333.1701992918.386.513.jpg?c=1', 'MOTION / Motors / Motor Mounts / Motor Mounts for REV Robotics Motors', 'gobilda'),
  ('Motor Mount for 5000 Series Motor', '1704-1632-0001', 'Take heed of the speed of the 5000 Series Motor!—but you don''t need to worry about that until after you''ve mounted your motor! This handy Motor Mount is specially designed to fasten to the face of a 5000 Series Motor and provide you with the convenient installation options you expect from the goBILDA® pattern. Each included M3 screw has a nylon patch which ensures that when they''re fastened into the 25mm bolt-circle of your motor (with a #2 Phillips screwdriver), they''re there to stay. The…', 'goBILDA', null, true, 'https://www.gobilda.com/motor-mount-for-5000-series-motor/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/2450/images/15427/Ang1__36676__15793.1761256051.386.513.jpg?c=1', 'MOTION / Motors / Motor Mounts', 'gobilda'),
  ('1800 Series Servo Pattern Plate (For Standard Size Servos)', '1800-0040-0001', 'This plate is built to house a standard size servo and space the output spline of the servo 48mm away from the center of the pattern at the end of the plate. This gives you the ability to install a gear on the servo and drive a spur gear that''s centered on the pattern.', 'goBILDA', null, true, 'https://www.gobilda.com/1800-series-servo-pattern-plate-for-standard-size-servos/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/369/images/2682/1800-0040-0001__41918__68186.1701991664.386.513.jpg?c=1', 'MOTION / Servos / Servo Mounts', 'gobilda'),
  ('1800 Series Servo Pattern Plate (For Large Size Servos)', '1800-0040-0002', 'This plate is built to house a large size servo and space the output spline of the servo 48mm away from the center of the pattern at the end of the plate. This gives you the ability to install a gear on the servo and drive a spur gear that''s centered with the pattern.', 'goBILDA', null, true, 'https://www.gobilda.com/1800-series-servo-pattern-plate-for-large-size-servos/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/371/images/2691/1800-0040-0002__05954__52083.1701991667.386.513.jpg?c=1', 'MOTION / Servos / Servo Mounts', 'gobilda'),
  ('1801 Series Servo Plate (For Standard Size Servos)', '1801-0040-0001', 'This simple plate is intended to hold a standard size servo. The slotted holes on the sides of the plate offer adjustability so that you can shift the plate as needed - great when adjusting gear-mesh!', 'goBILDA', null, true, 'https://www.gobilda.com/1801-series-servo-plate-for-standard-size-servos/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/373/images/2699/1801-0040-0001-REV1__86821__52415.1701991670.386.513.jpg?c=1', 'MOTION / Servos / Servo Mounts', 'gobilda'),
  ('1801 Series Servo Plate (For Large Size Servos)', '1801-0048-0002', 'This simple plate is intended to hold a large size servo. The slotted holes on the sides of the plate offer adjustability so that you can set your gear mesh when driving external gears off the servo.', 'goBILDA', null, true, 'https://www.gobilda.com/1801-series-servo-plate-for-large-size-servos/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/374/images/2704/1801-0048-0002__25042__46774.1701991671.386.513.jpg?c=1', 'MOTION / Servos / Servo Mounts', 'gobilda'),
  ('1802 Series Servo Frame (43mm Width, for Standard Size Servos)', '1802-0043-0001', 'This servo frame works with standard size servos. The threaded holes on the sides allow the mount to be fastened inside 1120 Series Channel or can be used to tie two 1121 Series Low-Side Channels together. The plethora of holes on each side allows you to align with the standard 32mm pattern, or the 24mm pattern between the 14mm holes of channel, both leaving the servo perfectly concentric with the 14mm hole above. The threaded holes on the end of the channel can be used as an alternate method…', 'goBILDA', null, true, 'https://www.gobilda.com/1802-series-servo-frame-43mm-width-for-standard-size-servos/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/376/images/2723/1802-0043-0001-REV1-Ang1__30896__19700.1701991677.386.513.jpg?c=1', 'MOTION / Servos / Servo Mounts', 'gobilda'),
  ('1802 Series Servo Frame (43mm Width, for Large Size Servos)', '1802-0043-0002', 'The large size servo frame has threaded holes on the sides and end, as well as thru-holes on the face. The threaded holes on the sides allow you to mount the frame across 1120 Series U-Channel. The threaded holes on the end are useful if you want to stand the servo up perpendicular to a flat surface.', 'goBILDA', null, true, 'https://www.gobilda.com/1802-series-servo-frame-43mm-width-for-large-size-servos/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/378/images/2732/1802-0043-0002__34181__65169.1701991679.386.513.jpg?c=1', 'MOTION / Servos / Servo Mounts', 'gobilda'),
  ('1804 Series Servo Stand (32-1)', '1804-0032-0001', 'Servo stands have holes spaced 32mm apart to align with the grid pattern and then provide 4 threaded holes to fasten a standard size servo to. The included M4 socket head screws and washers are used to fasten your standard size servo to the top of the stands.', 'goBILDA', null, true, 'https://www.gobilda.com/1804-series-servo-stand-32-1/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/380/images/2746/1804-0032-0001-Rev1__51778__93768.1701991682.386.513.jpg?c=1', 'MOTION / Servos / Servo Mounts', 'gobilda'),
  ('Steel 90° Servo Mounting Brackets (for Standard Size Servo)', '1806-0001-0001', 'When you call for compactness, these 90° Servo Mounting Brackets answer! Designed specifically for mounting a standard size servo to a flat surface, they leave the servo''s spline a crisp 20mm from that surface; when installed as such, their 4mm mounting holes are a convenient 48mm apart. Speaking of convenience: these brackets not only come with the screws and washers to fasten the servo to the brackets, but also with Nylock nuts and 10mm socket head screws so that you don''t have to go looking…', 'goBILDA', null, true, 'https://www.gobilda.com/steel-90-servo-mounting-brackets-for-standard-size-servo/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/2471/images/16547/Ang2__62859.1776459414.386.513.jpg?c=1', 'MOTION / Servos / Servo Mounts', 'gobilda'),
  ('1900 Series Single Servo Arm (24 Tooth Spline, 32mm Length)', '1900-0024-0104', 'Control a linkage, flap, lever or pushrod with this 24 tooth servo arm. The holes are equally spaced 8mm apart so that they will align with any of the beams or grid-based items.', 'goBILDA', null, true, 'https://www.gobilda.com/1900-series-single-servo-arm-24-tooth-spline-32mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/372/images/2703/1900-0024-0104__35555__31209.1701991671.386.513.jpg?c=1', null, 'gobilda'),
  ('1900 Series Single Servo Arm (25 Tooth Spline, 32mm Length)', '1900-0025-0104', 'Control a linkage, flap, lever or pushrod with this 25 tooth servo arm. The holes are equally spaced 8mm apart so that they will align with any of the beams or grid-based items.', 'goBILDA', null, true, 'https://www.gobilda.com/1900-series-single-servo-arm-25-tooth-spline-32mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/375/images/2711/1900-0025-0104__69292__78268.1701991673.386.513.jpg?c=1', 'MOTION / Servos / Servo Attachments', 'gobilda'),
  ('1902 Series Dual Servo Arm (24 Tooth Spline, 64mm Length)', '1902-0024-0204', 'The dual arm is a two sided version of the single servo arm. Having two equal sides allows you to create a push-pull setup for situations where you want to actuate two surfaces using a single servo.', 'goBILDA', null, true, 'https://www.gobilda.com/1902-series-dual-servo-arm-24-tooth-spline-64mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/377/images/2726/1902-0024-0204__50613__81887.1701991677.386.513.jpg?c=1', null, 'gobilda'),
  ('1902 Series Dual Servo Arm (25 Tooth Spline, 64mm Length)', '1902-0025-0204', 'The dual arm is a two sided version of the single servo arm. Having two equal sides allows you to create a push-pull setup for situations where you want to actuate two surfaces using a single servo.', 'goBILDA', null, true, 'https://www.gobilda.com/1902-series-dual-servo-arm-25-tooth-spline-64mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/379/images/2737/1902-0025-0204__47051__36924.1701991680.386.513.jpg?c=1', 'MOTION / Servos / Servo Attachments', 'gobilda'),
  ('1906 Series Low-Profile Servo Hub (24 Tooth Spline, 32mm Diameter)', '1906-0024-0032', 'This 24 tooth servo hub is a sleek and slim horn that allows you to fasten nearly any part with the goBILDA® 16mm square pattern to the top of a servo. The 14mm diameter protrusion acts as a centering mechanism for mating components that have a 14mm bore.', 'goBILDA', null, true, 'https://www.gobilda.com/1906-series-low-profile-servo-hub-24-tooth-spline-32mm-diameter/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/381/images/11508/1906-0024-0032_Ang1__50461.1711997046.386.513.jpg?c=1', null, 'gobilda'),
  ('1906 Series Low-Profile Servo Hub (25 Tooth Spline, 32mm Diameter)', '1906-0025-0032', 'This 25 tooth servo hub is a sleek and slim horn that allows you to fasten nearly any part with the 16mm pattern to the top of a servo. The 14mm diameter protrusion acts as a centering mechanism for mating components that have a 14mm bore.', 'goBILDA', null, true, 'https://www.gobilda.com/1906-series-lightweight-servo-hub-25-tooth-spline-32mm-diameter/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/382/images/14291/1906-0025-0032_Ang1__66502__88537.1746125007.386.513.jpg?c=1', 'MOTION / Servos / Servo Attachments', 'gobilda'),
  ('1908 Series Servo Hub (24 Tooth Spline, 32mm Diameter)', '1908-0024-0032', 'The 1908 Series Servo Hub is 32mm in diameter and 6mm thick so that you can support it with a bearing or clamp around it using a 32mm ID clamping mount. It contains both threaded and thru-holes on the 16mm pattern so that you can fasten almost any goBILDA® component to the top. The counterbored top will recess the servo screw down below the surface to keep from interfering with mating parts.', 'goBILDA', null, true, 'https://www.gobilda.com/1908-series-servo-hub-24-tooth-spline-32mm-diameter/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/386/images/2776/1908-0024-0032__61309__02605.1701991690.386.513.jpg?c=1', null, 'gobilda'),
  ('1908 Series Servo Hub (25 Tooth Spline, 32mm Diameter)', '1908-0025-0032', 'The 1908 Series Servo Hub is 32mm in diameter and 6mm thick so that you can support it with a bearing or clamp around it using a 32mm ID clamping mount. It contains both threaded and thru-holes on the 16mm pattern so that you can fasten almost any goBILDA® component to the top. The counterbored top will recess the servo screw down below the surface to keep from interfering with mating parts.', 'goBILDA', null, true, 'https://www.gobilda.com/1908-series-servo-hub-25-tooth-spline-32mm-diameter/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/388/images/2787/1908-0025-0032__03687__75295.1701991694.386.513.jpg?c=1', 'MOTION / Servos / Servo Attachments', 'gobilda'),
  ('1910 Series Servo Hub Shaft (24 Tooth Spline, 10mm Shaft Diameter, 33mm Length)', '1910-0024-1033', 'The hub shaft is an integral part of a ServoBlock. The long neck allows it to be supported with a 10mm pillow block for heavy duty applications. The 32mm OD top is able to work with 32mm clamps as well as 32mm bearings. The pattern contains both thru-holes and tapped holes to be compatible with almost any goBILDA part.', 'goBILDA', null, true, 'https://www.gobilda.com/1910-series-servo-hub-shaft-24-tooth-spline-10mm-shaft-diameter-33mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/390/images/2797/1910-0024-1033-Patented__30905__99181.1701991698.386.513.jpg?c=1', null, 'gobilda'),
  ('1910 Series Servo Hub Shaft (25 Tooth Spline, 8mm Shaft Diameter, 16mm Length)', '1910-0025-0816', 'Though most servos support their splined output shafts with internal bearings, servos'' internal bearings aren''t designed for significant radial loads. This Servo Hub-Shaft comes to the rescue for 25 tooth (H25T) splined servos! It''s designed to be supported by an external 8mm round bore ball bearing. The output goBILDA® 16mm pattern, offering four of each thru- and threaded holes, allows this Hub-Shaft to drive hub-mounted motion components such as gears, wheels, control arms, and more across…', 'goBILDA', null, true, 'https://www.gobilda.com/1910-series-servo-hub-shaft-25-tooth-spline-8mm-shaft-diameter-16mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1739/images/9171/1910-0025-0816_Ang1__00688__74414.1740174419.386.513.jpg?c=1', 'MOTION / Servos / Servo Attachments', 'gobilda'),
  ('1910 Series Servo Hub Shaft (25 Tooth Spline, 10mm Shaft Diameter, 33mm Length)', '1910-0025-1033', 'The hub shaft is an integral part of a ServoBlock. The long neck allows it to be supported with a 10mm pillow block for heavy duty applications. The 32mm OD top is able to work with 32mm clamps as well as 32mm bearings. The pattern contains both thru-holes and tapped holes to be compatible with almost any goBILDA part.', 'goBILDA', null, true, 'https://www.gobilda.com/1910-series-servo-hub-shaft-25-tooth-spline-10mm-shaft-diameter-33mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/391/images/2806/1910-0025-1033-Beauty__80153__35214.1701991701.386.513.jpg?c=1', 'MOTION / Servos / Servo Attachments', 'gobilda'),
  ('10mm Round Servo Shaft (24 Tooth Spline, 36mm Length)', '1911-0024-1036', 'Attaching a round shaft to a servo spline unlocks many possibilities. The shaft is able to slide through a 10mm bearing so that it can be used in applications that would otherwise exert a heavy radial load on the servo. In order to fasten components to the shaft, use a 10mm clamping hub which provides the ability to adjust the height as well as clock the mating part with ease.', 'goBILDA', null, true, 'https://www.gobilda.com/10mm-round-servo-shaft-24-tooth-spline-36mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/383/images/2753/1911-0024-1036-Ang1-Patented__47396__28542.1701991685.386.513.jpg?c=1', null, 'gobilda'),
  ('8mm Round Servo Shaft (25 Tooth Spline, 36mm Length)', '1911-0025-0836', 'Convert your servo''s H25T spline to an 8mm round shaft to unlock goBILDA® possibilities! This 36mm long servo shaft is ready to be supported by an 8mm ID bearing to isolate radial loads from your servo. This servo shaft''s round profile allows you to clock your hubs to it however you like. Just rotate the hub to your preferred position and clamp it to the servo shaft. You can then use it to drive a gear, sprocket, or pulley and put your project in motion!', 'goBILDA', null, true, 'https://www.gobilda.com/8mm-round-servo-shaft-25-tooth-spline-36mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1891/images/10144/1911-0025-0836-Ang1pat__01117__10909.1701994010.386.513.jpg?c=1', 'MOTION / Servos / Servo Attachments', 'gobilda'),
  ('10mm Round Servo Shaft (25 Tooth Spline, 36mm Length)', '1911-0025-1036', 'Attaching a round shaft to a servo spline unlocks many possibilities. The shaft is able to slide through a 10mm bearing so that it can be used in applications that would otherwise exert a heavy radial load on the servo. In order to fasten components to the shaft, use a 10mm clamping hub which provides the ability to adjust the height as well as clock the mating part with ease.', 'goBILDA', null, true, 'https://www.gobilda.com/10mm-round-servo-shaft-25-tooth-spline-36mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/384/images/2762/1911-0025-1036-Ang1-Patented__21696__48306.1701991687.386.513.jpg?c=1', 'MOTION / Servos / Servo Attachments', 'gobilda'),
  ('Aluminum Hub-Mount Control Arm (14mm Bore, 72mm Length)', '1914-0014-0072', 'A control-arm is exactly what it sounds like: a mechanical limb you can use to implement linkage-facilitated motion! This 72mm length control arm can be bolted to a goBILDA® hub, or any other goBILDA® component which rocks holes on the goBILDA® 16mm square pattern. A ball linkage, or beam, can be added to one(14) of the seven holes along the arm. As the control arm rotates, it will push or pull the linkage attached to it, and the hole the linkage is attached to will affect the amount of travel and…', 'goBILDA', null, true, 'https://www.gobilda.com/aluminum-hub-mount-control-arm-14mm-bore-72mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1610/images/16242/Ang1__32820.1773353316.386.513.jpg?c=1', 'MOTION / Control-Arms', 'gobilda'),
  ('Plastic Hub-Mount Control Arm (24mm Length)', '1916-0014-0024', 'This 24mm length control arm can be bolted to a goBILDA hub or other goBILDA component which has the 16mm square pattern. A ball linkage, or beam, can be added to the hole at the end of the arm. As the control arm rotates, it will push or pull the linkage attached to it.', 'goBILDA', null, true, 'https://www.gobilda.com/plastic-hub-mount-control-arm-24mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1657/images/8665/1916-0014-0024__52599__01430.1701993541.386.513.jpg?c=1', 'MOTION / Control-Arms', 'gobilda'),
  ('Plastic Hub-Mount Control Arm (48mm Length)', '1916-0014-0048', 'This 48mm length control arm can be bolted to a goBILDA hub or other goBILDA component which has the 16mm square pattern. A ball linkage, or beam, can be added to one(15) of the four holes along the arm. As the control arm rotates, it will push or pull the linkage attached to it. Which hole the linkage is attached to will affect the amount of travel and force the linkage receives.', 'goBILDA', null, true, 'https://www.gobilda.com/plastic-hub-mount-control-arm-48mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1659/images/8676/1916-0014-0048__48184__72644.1701993543.386.513.jpg?c=1', 'MOTION / Control-Arms', 'gobilda'),
  ('Plastic Hub-Mount Control Arm (72mm Length)', '1916-0014-0072', 'This 72mm length control arm can be bolted to a goBILDA hub or other goBILDA components which has the 16mm square pattern. A ball linkage, or beam, can be added to one(16) of the seven holes along the arm. As the control arm rotates, it will push or pull the linkage attached to it. Which hole the linkage is attached to will affect the amount of travel and force the linkage receives.', 'goBILDA', null, true, 'https://www.gobilda.com/plastic-hub-mount-control-arm-72mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1661/images/8687/1916-0014-0072__73587__72461.1701993547.386.513.jpg?c=1', 'MOTION / Control-Arms', 'gobilda'),
  ('Plastic Dual Hub-Mount Control Arm (24mm Length)', '1917-0014-0024', 'This 24mm length control arm provides two arms, directly opposite one(17) another, for putting your project in motion! It can be bolted to a hub (or any component) that has the goBILDA® 16mm hole pattern. A ball linkage or beam can be attached to a hole at each end of the arm. When rotated, one(18) side of the control arm will push its linkage, while the opposing side will pull its linkage in the opposite direction. The ABS plastic is a rigid material that''s also resilient to shock loads.', 'goBILDA', null, true, 'https://www.gobilda.com/plastic-dual-hub-mount-control-arm-24mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1959/images/10587/1917-0014-0024__70355__99412.1701994154.386.513.jpg?c=1', 'MOTION / Control-Arms', 'gobilda'),
  ('Plastic Dual Hub-Mount Control Arm (48mm Length)', '1917-0014-0048', 'This 48mm length control arm provides two arms, directly opposite one(19) another, for putting your project in motion! It can be bolted to a hub (or any component) that has the goBILDA® 16mm hole pattern. A ball linkage or beam can be attached to a hole at each end of the arm. When rotated, one(20) side of the control arm will push its linkage, while the opposing side will pull its linkage in the opposite direction. The ABS plastic is a rigid material that''s also resilient to shock loads.', 'goBILDA', null, true, 'https://www.gobilda.com/plastic-dual-hub-mount-control-arm-48mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1952/images/10555/1917-0014-0048__16339__31038.1701994143.386.513.jpg?c=1', 'MOTION / Control-Arms', 'gobilda'),
  ('Plastic Dual Hub-Mount Control Arm (72mm Length)', '1917-0014-0072', 'This 72mm length control arm provides two arms, directly opposite one(21) another, for putting your project in motion! It can be bolted to a hub (or any component) that has the goBILDA® 16mm hole pattern. A ball linkage or beam can be attached to a hole at each end of the arm. When rotated, one(22) side of the control arm will push its linkage, while the opposing side will pull its linkage in the opposite direction. The ABS plastic is a rigid material that''s also resilient to shock loads.', 'goBILDA', null, true, 'https://www.gobilda.com/plastic-dual-hub-mount-control-arm-72mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1954/images/10563/1917-0014-0072__21633__92525.1701994146.386.513.jpg?c=1', 'MOTION / Control-Arms', 'gobilda'),
  ('Plastic 90 Degree Hub-Mount Control Arm (72mm Length)', '1918-0014-0072', 'This 90°, 72mm length bell-crank-style control arm provides two arms with just the right angle for putting your project in motion! It can be bolted to a hub (or any component) that has the goBILDA® 16mm hole pattern. A ball linkage or beam can be attached to a hole at each end of the arm. The ABS plastic is a rigid material that''s also resilient to shock loads.', 'goBILDA', null, true, 'https://www.gobilda.com/plastic-90-degree-hub-mount-control-arm-72mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1957/images/10571/1918-0014-0072__82027__11094.1701994149.386.513.jpg?c=1', 'MOTION / Control-Arms', 'gobilda'),
  ('Plastic Hub-Mount Disc (14mm Bore, 96mm Diameter)', '1919-0014-0096', 'Need a control arm, a turntable, a wheel–or all three? This versatile 96mm diameter disc can do it all! Its ABS plastic construction gives it good rigidity while also providing resilience to shock loads. Its center pattern allows for connection to components with the goBILDA® 16mm hole pattern. Meanwhile, the holes on the outer edges are perfect for attaching linkages in a motion assembly.', 'goBILDA', null, true, 'https://www.gobilda.com/plastic-hub-mount-disc-14mm-bore-96mm-diameter/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1958/images/10580/1919-0014-0096__12603__45146.1701994152.386.513.jpg?c=1', 'MOTION / Control-Arms', 'gobilda'),
  ('Plastic Hub-Mount Disc (14mm Bore, 144mm Diameter)', '1919-0014-0144', 'Need a control arm, a turntable, a wheel–or all three? This versatile 144mm diameter disc can do it all! Its ABS plastic construction gives it good rigidity while also providing resilience to shock loads. Its center pattern allows for connection to components with the goBILDA® 16mm hole pattern. Meanwhile, the holes on the outer edges are perfect for attaching linkages in a motion assembly.', 'goBILDA', null, true, 'https://www.gobilda.com/plastic-hub-mount-disc-14mm-bore-144mm-diameter/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1960/images/10595/1919-0014-0144__40962__37935.1701994156.386.513.jpg?c=1', 'MOTION / Control-Arms', 'gobilda'),
  ('Plastic Hub-Mount Disc (14mm Bore, 192mm Diameter)', '1919-0014-0192', 'Need a control arm, a turntable, a wheel–or all three? This versatile 192mm diameter disc can be all of those and more! Its ABS plastic construction gives it good rigidity while also providing resilience to shock loads. Its center pattern allows for connection to components with the goBILDA® 16mm hole pattern. Meanwhile, the holes on the outer edges are perfect for attaching linkages in a motion assembly.', 'goBILDA', null, true, 'https://www.gobilda.com/plastic-hub-mount-disc-14mm-bore-192mm-diameter/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1962/images/10604/1919-0014-0192__59408__86374.1701994159.386.513.jpg?c=1', 'MOTION / Control-Arms', 'gobilda'),
  ('Plastic Hub-Mount Disc (14mm Bore, 240mm Diameter)', '1919-0014-0240', 'Need a control arm, a turntable, a wheel–or all three? This versatile 240mm diameter disc can be all of those and more! Its ABS plastic construction gives it good rigidity while also providing resilience to shock loads. Its center pattern allows for connection to components with the goBILDA® 16mm hole pattern. Meanwhile, the holes on the outer edges are perfect for attaching linkages in a motion assembly.', 'goBILDA', null, true, 'https://www.gobilda.com/plastic-hub-mount-disc-14mm-bore-240mm-diameter/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1964/images/10620/1919-0014-0240__95146__27814.1701994164.386.513.jpg?c=1', 'MOTION / Control-Arms', 'gobilda'),
  ('Plastic Hub-Mount Disc (32mm Bore, 96mm Diameter)', '1920-0032-0096', 'Need a control arm, a turntable, a wheel–or all three? This versatile 96mm diameter disc can do it all! Its ABS plastic construction gives it good rigidity while also providing resilience to shock loads. Its center pattern allows for connection to components with the goBILDA® 32mm hole pattern. Meanwhile, the holes on the outer edges are perfect for attaching linkages in a motion assembly.', 'goBILDA', null, true, 'https://www.gobilda.com/plastic-hub-mount-disc-32mm-bore-96mm-diameter/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1967/images/10628/1920-0032-0096__30236__37758.1701994167.386.513.jpg?c=1', 'MOTION / Control-Arms', 'gobilda'),
  ('Plastic Hub-Mount Disc (32mm Bore, 144mm Diameter)', '1920-0032-0144', 'Need a control arm, a turntable, a wheel–or all three? This versatile 144mm diameter disc can do it all! Its ABS plastic construction gives it good rigidity while also providing resilience to shock loads. Its center pattern allows for connection to components with the goBILDA® 32mm hole pattern. Meanwhile, the holes on the outer edges are perfect for attaching linkages in a motion assembly.', 'goBILDA', null, true, 'https://www.gobilda.com/plastic-hub-mount-disc-32mm-bore-144mm-diameter/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1968/images/10641/1920-0032-0144__80789__55303.1701994170.386.513.jpg?c=1', 'MOTION / Control-Arms', 'gobilda'),
  ('Plastic Hub-Mount Disc (32mm Bore, 192mm Diameter)', '1920-0032-0192', 'Need a control arm, a turntable, a wheel–or all three? This versatile 192mm diameter disc can do it all! Its ABS plastic construction gives it good rigidity while also providing resilience to shock loads. Its center pattern allows for connection to components with the goBILDA® 32mm hole pattern. Meanwhile, the holes on the outer edges are perfect for attaching linkages in a motion assembly.', 'goBILDA', null, true, 'https://www.gobilda.com/plastic-hub-mount-disc-32mm-bore-192mm-diameter/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1970/images/10658/1920-0032-0192__16527__10271.1701994176.386.513.jpg?c=1', 'MOTION / Control-Arms', 'gobilda'),
  ('Plastic Hub-Mount Disc (32mm Bore, 240mm Diameter)', '1920-0032-0240', 'Need a control arm, a turntable, a wheel–or all three? This versatile 240mm diameter disc can do it all! Its ABS plastic construction gives it good rigidity while also providing resilience to shock loads. Its center pattern allows for connection to components with the goBILDA® 32mm hole pattern. Meanwhile, the holes on the outer edges are perfect for attaching linkages in a motion assembly.', 'goBILDA', null, true, 'https://www.gobilda.com/plastic-hub-mount-disc-32mm-bore-240mm-diameter/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1963/images/10612/1920-0032-0240__47535__51465.1701994162.386.513.jpg?c=1', 'MOTION / Control-Arms', 'gobilda'),
  ('Plastic Servo Hub (H25T Spline, 32mm Diameter)', '1921-0025-0032', 'This servo hub is perfect for driving goBILDA® components from a 25 tooth (H25T) servo! 16mm pattern components such as gears, sprockets, and pulleys all have a home on the hub thanks to four thru-holes designed for M4 thread-forming screws. Alternatively, four slots of the same pattern can put your conventional machine screws to work by capturing M4 nuts in hex counterbores, and 24mm spacing across slots provides for the attachment of linear parts like beams.', 'goBILDA', null, true, 'https://www.gobilda.com/plastic-servo-hub-h25t-spline-32mm-diameter/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1745/images/9213/1921-0025-0032__67830__28823.1701993715.386.513.jpg?c=1', 'MOTION / Servos / Servo Attachments', 'gobilda'),
  ('8mm REX® Servo Shaft (25 Tooth Spline, 36mm Length)', '1922-0025-0036', 'Convert your servo''s H25T spline to an 8mm REX® shaft to unlock tons of goBILDA® possibilities! This 36mm long servo shaft is ready to be supported by an 8mm REX® bearing to isolate radial loads from your servo. And since the positive-drive 8mm REX™ profile is a staple of the goBILDA® ecosystem, whether you want to use this servo shaft to rotate a gear, sprocket, pulley or hub, you''re sure to find an option for your build.', 'goBILDA', null, true, 'https://www.gobilda.com/8mm-rex-servo-shaft-25-tooth-spline-36mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1886/images/10130/1922-0025-0036-Ang1pat__95334__38770.1701994006.386.513.jpg?c=1', 'MOTION / Servos / Servo Attachments', 'gobilda'),
  ('12mm REX® Servo Shaft (25 Tooth Spline, 48mm Length)', '1923-0025-0048', 'Convert your servo''s H25T spline to an 12mm REX® shaft to unlock tons of goBILDA® possibilities! This 48mm long servo shaft is ready to be supported by a 12mm round bearing to isolate radial loads from your servo. The positive-drive 12mm REX® profile has compatibility with heavy-duty bearings, hubs, and more in the goBILDA® ecosystem.', 'goBILDA', null, true, 'https://www.gobilda.com/12mm-rex-servo-shaft-25-tooth-spline-48mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/2092/images/11442/1923-0025-0048-Ang1__86430.1710883592.386.513.jpg?c=1', 'MOTION / Servos / Servo Attachments', 'gobilda'),
  ('Clamping Control-Arm (8mm REX® Bore, 48mm Length)', '1925-4008-0048', 'Get a grip on positive-drive motion with the 8mm REX® Clamping Control-Arm! This all-in-one(23) control-arm is a sleek and simple way to transfer torque from an 8mm REX® shaft into a linkage in order to actuate mechanisms like an arm, a door, or the claw of a ''bot. The profile-matched bore combines with the gorilla-like grip of the clamping mechanism to create a superb hold on an 8mm REX™ shaft. And while it stays tucked away to allow nearby components to move freely, the pinch-bolt remains…', 'goBILDA', null, true, 'https://www.gobilda.com/clamping-control-arm-8mm-rex-bore-48mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/2362/images/14434/1925-4008-0048_Ang1__37371__27849.1739312801.386.513.jpg?c=1', 'MOTION / Control-Arms', 'gobilda'),
  ('2000 Series Dual Mode Servo (25-1)', '2000-0025-0001', 'This servo has been replaced by the 2000 Series Dual Mode Servo (25-2) designed with ultra stout steel gear train.', 'goBILDA', null, true, 'https://www.gobilda.com/2000-series-dual-mode-servo-25-1/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/742/images/4256/2000-0025-0001__71131__91195.1701992142.386.513.jpg?c=1', null, 'gobilda'),
  ('2000 Series Dual Mode Servo (25-2, Torque)', '2000-0025-0002', 'The goBILDA 2000-0025-0002 is a descendant of the popular 2000-0025-0001 servo. The 25-2 received some noteworthy updates including an ultra stout steel gear train, more torque and a new top case. Like its predecessor, the 25-2 boasts two different modes which allow it to fill a variety of roles on your robot or project. In the default mode, the servo is able to rotate 300 degrees while having positioning feedback. In this mode, the PWM signal will determine the position of the servo. Using…', 'goBILDA', null, true, 'https://www.gobilda.com/2000-series-dual-mode-servo-25-2-torque/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1190/images/5970/2000-0025-0002__75515__83589.1701992706.386.513.jpg?c=1', 'MOTION / Servos / Standard Size Servos', 'gobilda'),
  ('2000 Series Dual Mode Servo (25-3, Speed)', '2000-0025-0003', 'Meet the Dual Mode ''SPEED'' Servo. This servo is essentially the original 2000-0025-0002 ''TORQUE'' Servo, but with a lower ratio to achieve a quicker transit speed! Over 2x faster than its counterpart, this servo saves valuable time where it counts! Just like the 25-2, this servo boasts two different modes which allow it to fill a variety of roles on your robot or project. In the default mode, the servo is able to rotate 300 degrees while having positioning feedback. In this mode, the PWM signal…', 'goBILDA', null, true, 'https://www.gobilda.com/2000-series-dual-mode-servo-25-3-speed/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1346/images/6599/2000-0025-0003__96108__04560.1701992903.386.513.jpg?c=1', 'MOTION / Servos / Standard Size Servos', 'gobilda'),
  ('2000 Series Dual Mode Servo (25-4, Super Speed)', '2000-0025-0004', 'Meet the Dual Mode ''SUPER SPEED'' Servo. This servo is essentially an even faster version of the 2000-0025-0003 ''SPEED'' Servo, reaching speeds of up to 290RPM! Just like the other 2000 Series servos, this servo boasts two different modes which allow it to fill a variety of roles on your robot or project. In the default mode, the servo is able to rotate 300 degrees while having positioning feedback. In this mode, the PWM signal will determine the position of the servo. Using the 3102 Series Dual…', 'goBILDA', null, true, 'https://www.gobilda.com/2000-series-dual-mode-servo-25-4-super-speed/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1429/images/7077/2000-0025-0004__86404__65600.1701993055.386.513.jpg?c=1', 'MOTION / Servos / Standard Size Servos', 'gobilda'),
  ('2000 Series 5-Turn, Dual Mode Servo (25-2, Torque)', '2000-0025-0502', 'Like the other 2000 Series goBILDA Servos, the 2000-0025-0502 boasts two different modes. In the default mode, the servo is able to rotate while having positioning feedback. In this mode, the PWM signal will determine the position of the servo. Using the 3102 Series Dual Mode Servo Programmer (1-1) the servo can be toggled into continuous rotation mode. In this mode, the servo will have proportional speed control based on the PWM signal that you send with your servo controller.', 'goBILDA', null, true, 'https://www.gobilda.com/2000-series-5-turn-dual-mode-servo-25-2-torque/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1621/images/8472/2000-0025-0502__60168__38645.1701993477.386.513.jpg?c=1', 'MOTION / Servos / Standard Size Servos', 'gobilda'),
  ('2000 Series 5-Turn, Dual Mode Servo (25-3, Speed)', '2000-0025-0503', 'Meet the Dual Mode 5-Turn ''SPEED'' Servo. Like the other 2000 Series goBILDA® servos, the 2000-0025-0503 boasts two different modes: Default Mode In Default Mode the servo is able to rotate while having positioning feedback. In this mode, the PWM signal will determine the position of the servo. Continuous Rotation Mode Using the 3102 Series Dual Mode Servo Programmer (1-1) the servo can be toggled into continuous rotation mode. In this mode, the servo will have proportional speed control based…', 'goBILDA', null, true, 'https://www.gobilda.com/2000-series-5-turn-dual-mode-servo-25-3-speed/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1741/images/9189/2000-0025-0503__85076__60600.1701993707.386.513.jpg?c=1', 'MOTION / Servos / Standard Size Servos', 'gobilda'),
  ('2000 Series 5-Turn, Dual Mode Servo (25-4, Super Speed)', '2000-0025-0504', 'Meet the Dual Mode 5-Turn ''SUPER SPEED'' Servo! Like the other 2000 Series goBILDA® servos, the 2000-0025-0504 boasts two different modes: Default Mode In Default Mode the servo is able to rotate while having positioning feedback. In this mode, the PWM signal will determine the position of the servo. Continuous Rotation Mode Using the 3102 Series Dual Mode Servo Programmer (1-1) the servo can be toggled into continuous rotation mode. In this mode, the servo will have proportional speed control…', 'goBILDA', null, true, 'https://www.gobilda.com/2000-series-5-turn-dual-mode-servo-25-4-super-speed/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1732/images/9100/2000-0025-0504__64851__69891.1701993681.386.513.jpg?c=1', 'MOTION / Servos / Standard Size Servos', 'gobilda'),
  ('Proton Servo (Steel Gears, 180° Rotation, Torque Ratio)', '2002-0180-0002', 'The goBILDA® Proton Servo is a standard size servo offering essential servo function on a budget. There are two versions of the Proton: ''Torque'' and ''Speed''. Though their gear ratios differ, they are identical in every other way. The ''Torque'' version sacrifices speed to optimize its performance in higher torque applications. While makers of all levels can appreciate the steel gears that form the Proton''s core, the nucleus of the design is beginner-friendly accessibility ! That''s why the…', 'goBILDA', null, true, 'https://www.gobilda.com/proton-servo-steel-gears-180-rotation-torque-ratio/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/2056/images/11279/2002-0180-0002-Ang1__68751__85830.1707747410.386.513.jpg?c=1', 'MOTION / Servos / Standard Size Servos', 'gobilda'),
  ('Proton Servo (Steel Gears, 180° Rotation, Speed Ratio)', '2002-0180-0003', 'The goBILDA® Proton Servo is a standard size servo offering essential servo function on a budget. There are two versions of the Proton: ''Torque'' and ''Speed''. Though their gear ratios differ, they are identical in every other way. The ''Speed'' version sacrifices torque to optimize its performance in higher speed applications. While makers of all levels can appreciate the steel gears that form the Proton''s core, the nucleus of the design is beginner-friendly accessibility ! That''s why the…', 'goBILDA', null, true, 'https://www.gobilda.com/proton-servo-steel-gears-180-rotation-speed-ratio/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/2057/images/11288/2002-0180-0003-Ang1__19691__05342.1707747410.386.513.jpg?c=1', 'MOTION / Servos / Standard Size Servos', 'gobilda'),
  ('Axon MINI Servo MK2', '2004-0025-0001', 'The Axon MINI Servo MK2 is a favorite among FTC teams for a reason: it packs incredible brushless performance into a low-profile package that is shorter than a conventional standard-sized servo. This premium actuator is a go-to for high-speed claws, intake pivots, and compact subassemblies where space is tight and power is a necessity. Durability Axon servos are known for their durability. This servo features a robust steel gear train encased in a rugged aluminum housing for maximum…', 'goBILDA', null, true, 'https://www.gobilda.com/axon-mini-servo-mk2/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/2547/images/16931/r%25252F299%25252FAng1__60509__84822.1783711196.386.513.jpg?c=1', 'MOTION / Servos / Standard Size Servos', 'gobilda'),
  ('Axon MAX Servo MK2', '2004-0025-0002', 'The Axon MAX Servo MK2 is a favorite among FTC teams for a reason: it packs incredible brushless performance and massive torque into a standard-sized package. This premium actuator is a go-to for heavy-duty articulating joints, high-load intakes, and mechanisms where maximum strength and reliability are absolute necessities. Durability Axon servos are known for their durability. This servo features a robust steel gear train encased in a rugged aluminum housing for maximum reliability under…', 'goBILDA', null, true, 'https://www.gobilda.com/axon-max-servo-mk2/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/2548/images/16945/q%25252F917%25252FAng1__13593__78125.1783711202.386.513.jpg?c=1', 'MOTION / Servos / Standard Size Servos', 'gobilda'),
