  ('6mm D-Shaft (Stainless Steel, 60mm Length)', '2101-0006-0060', null, 'goBILDA', null, true, 'https://www.gobilda.com/2101-series-stainless-steel-d-shaft-6mm-diameter-60mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/417/images/2909/2101-0006-0060__78920__74209.1701991730.386.513.jpg?c=1', 'MOTION / Shafting & Tubing / Stainless Steel D-Shafting', 'gobilda'),
  ('6mm D-Shaft (Stainless Steel, 70mm Length)', '2101-0006-0070', null, 'goBILDA', null, true, 'https://www.gobilda.com/6mm-d-shaft-stainless-steel-70mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/419/images/2917/2101-0006-0070__27436__71719.1701991732.386.513.jpg?c=1', 'MOTION / Shafting & Tubing / Stainless Steel D-Shafting', 'gobilda'),
  ('6mm D-Shaft (Stainless Steel, 80mm Length)', '2101-0006-0080', 'The 80mm length of D-shaft is heavily used in builds as it''s able to run through both sides of 1120 Series U-Channel. This leaves enough room on either side to install a gear, hub, or collar in order to restrict it from moving axially.', 'goBILDA', null, true, 'https://www.gobilda.com/6mm-d-shaft-stainless-steel-80mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/421/images/2925/2101-0006-0080__40929__75927.1701991734.386.513.jpg?c=1', 'MOTION / Shafting & Tubing / Stainless Steel D-Shafting', 'gobilda'),
